import { IContentfulLink } from "@/core/types/contentful-types";
import { Dispatch } from "react";
import {
  CalendarDateResponse,
  DateSlot,
  EntryVariant,
  Product,
  TimeLimits,
  VISITOR_CATEGORY,
  VisitorCategory,
} from "../../services/purchase-flow-service-types";
import { IGLKMyParksEntranceWithProductId, IGLKMyParksTimeSlot, ITimeSlot } from "../../time-slots";
import { TextBlock } from "../../../stores/text-block-store";
import { LabelKey } from "@/core/labels/i18n";
import { ShowProps } from "@/core/components/primitives/calendar/types/calendar-types";
import { OpeningHoursItem } from "@parksandresorts/webapiproxy-types";

export type Action =
  | { type: ActionType.DEBUG; payload: unknown }
  | { type: ActionType.INITIALIZE; payload: any }
  | {
      type: ActionType.CHANGE_STEP;
      payload: {
        stepIndex: number;
      };
    }
  | { type: ActionType.CHANGE_QUANTITY; payload: { category: VisitorCategory["id"]; quantity: number } }
  | { type: ActionType.COMPLETE_STEP; payload: { completedStep: Step } }
  | {
      type: ActionType.SELECT_DATE;
      payload: { selectedDate: Date; opens: Date; closing: Date; products: Array<Product>; hideVariant: boolean };
    }
  | { type: ActionType.SELECT_MONTH; payload: { selectedMonth: Date } }
  | { type: ActionType.SELECT_VARIANT; payload: { selectedVariant: EntryVariant } }
  | { type: ActionType.SELECT_ENTRY_TIME; payload: any }
  | {
      type: ActionType.SELECT_TICKET;
      payload: { selectedTickets: SelectTicketCategoriesList; hasSubsequentChanges?: boolean };
    }
  | { type: ActionType.ADD_JETPASSES_TO_GUESTS; payload: { jetpassGuests: Array<GuestDTO> } }
  | { type: ActionType.UPDATE_UPSELL_PRODUCT; payload: { upsellProduct: SelectedUpsellProduct; selectedDate: Date } }
  | { type: ActionType.DELETE_UPSELL_PRODUCT; payload: { productId: number; date: Date } }
  | {
      type: ActionType.SELECT_MANDATORY_JETPASS;
      payload: { entrance: IGLKMyParksEntranceWithProductId; timeSlot: IGLKMyParksTimeSlot };
    };

export type Dispatchable = {
  dispatch: Dispatch<Action>;
};
export type StepProps = {
  stepIndex: number;
  onClickBack: () => void;
} & Dispatchable;

export enum ActionType {
  DEBUG = "DEBUG",
  INITIALIZE = "INITIALIZE",
  CHANGE_STEP = "CHANGE_STEP",
  CHANGE_QUANTITY = "CHANGE_QUANTITY",
  COMPLETE_STEP = "COMPLETE_STEP",
  SELECT_DATE = "SELECT_DATE",
  SELECT_MONTH = "SELECT_MONTH",
  SELECT_VARIANT = "SELECT_VARIANT",
  SELECT_ENTRY_TIME = "SELECT_ENTRY_TIME",
  SELECT_TICKET = "SELECT_TICKET",
  ADD_JETPASSES_TO_GUESTS = "ADD_JETPASSES_TO_GUESTS",
  UPDATE_UPSELL_PRODUCT = "UPDATE_UPSELL_PRODUCT",
  DELETE_UPSELL_PRODUCT = "DELETE_UPSELL_PRODUCT",
  SELECT_MANDATORY_JETPASS = "SELECT_MANDATORY_JETPASS",
}

export enum Step {
  FIXED_DATE = "FIXED_DATE",
  GROUP_SIZE = "GROUP_SIZE",
  SELECT_DATE = "SELECT_DATE",
  SELECT_ENTRY_TIME = "SELECT_ENTRY_TIME",
  SELECT_TICKET = "SELECT_TICKET",
  SELECT_MANDATORY_JETPASS = "SELECT_MANDATORY_JETPASS",
  SELECT_JETPASS = "SELECT_JETPASS",
  UPSELL = "UPSELL",
  SUMMARY = "SUMMARY",
}

export type StepData = {
  stepType: Step;
  titleLabelId?: LabelKey;
};

export type GroupAdmissionSharedState = {
  steps: Array<StepData>;
  activeStep: number;
  isCompleted: Map<Step, boolean>;
  quantity: Map<VisitorCategory["id"], number>;
  selectedDateOpeningHours: Pick<OpeningHoursItem, "opens" | "closing">;
  selectedDates: Map<string, VisitDate>;
  selectedDateProducts: Array<Product>;
  selectedDate: Date;
  variantsForSelectedDate: Array<EntryVariant["id"]>;
  selectedMonth: Date;
  selectedVariant: EntryVariant;
  guests: Array<Guest>;
  variants: Record<string, EntryVariant>;
  entryVariantType: string;
  preSelectedDate: boolean;
  isDisabledStep: Map<Step, boolean>;
};
export type GroupAdmissionState = GroupAdmissionSharedState & { checkoutVariant: "Klarna" };
export type CheckoutVariant = GroupAdmissionState["checkoutVariant"];

export type VisitDate = {
  date: Date;
  selectedEntryTime: SelectablePass;
  selectedUpsellProducts: Map<number, SelectedUpsellProduct>;
};
export type UpsellProductsForDate = {
  date: string;
  upsellProducts: Map<number, SelectedUpsellProduct>;
};

export type Guest = {
  id: string;
  name?: string;
  admissionProduct: AdmissionProduct;
  visitorCategory: VisitorCategory["id"];
};

export type AdmissionProduct = {
  id: number;
  dateSlotId: number;
  dateSlot: DateSlot;
  numberOfJetpassIncluded: number;
  timePassRequired: boolean;
  timeLimits: TimeLimits;
  selectedJetpasses: Array<SelectablePass>;
  selectedMandatoryJetpass?: SelectablePass;
};

export type SelectablePass = {
  timeSlotId: number;
  attractionId: number;
  productId: number;
  attractionName: string;
  timeSlotFrom: string;
  timeSlotTo: string;
  quantity?: number;
};

export type GuestDTO = {
  id: string;
  name: string;
  jetPasses: Array<SelectablePass>;
};
export type UpsellProduct = {
  /** This is the GLK-ID */
  id: number;
};

export type SummaryProduct = {
  id: number;
  date?: Date;
  name: string;
  quantity: number;
  rowValue: number;
  totalRowValue: number;
  timeSlot?: ITimeSlot | SelectablePass;
  visitorCategory?: string;
};

export type SelectedUpsellProduct = {
  productId: number;
  quantity: number;
  timeSlot?: ITimeSlot;
};

export type PurchaseFlowDate = {
  date: Date;
  opens: Date;
  closing: Date;
  products: Array<Product>;
  shows?: Array<ShowProps>;
  textBlocks?: Array<TextBlock>;
  visitorCategories: Array<VisitorCategory>;
  upsellProductsForDate: CalendarDateResponse["upsellProducts"];
};

export type DailyInformationData = {
  date: Date;
  opens: Date;
  closing: Date;
  anyDateSlotQuantityLeft: boolean;
  shows?: Array<ShowProps>;
  textBlocks?: Array<TextBlock>;
};

export type BannerData = {
  bannerText: any;
  bannerImage?: string;
  bannerLink?: IContentfulLink;
  openBannerLinkInNewTab?: boolean;
};

export type ProductWithQuantity = Product & { quantity: number };

export type CategoryListProps = {
  name: string;
  type: (typeof VISITOR_CATEGORY)[keyof typeof VISITOR_CATEGORY];
  selectedQuantityOfCategoryInGroup: number;
  productsByVariant?: Map<EntryVariant["id"], Array<ProductWithQuantity>>;
  sortIndex?: number;
};

export type SelectTicketCategoriesList = Map<string, CategoryListProps>;
