import { Dispatch, PropsWithChildren, SetStateAction, createContext, useContext, useState } from "react";
import { TimeLimits } from "../types/services/purchase-flow-service-types";

export type Pass = {
  id: number;
  productId: number;
  attractionId: number;
  startDateTime: string;
  endDateTime: string;
  attractionName: string;
};
export type Guest = {
  name: string;
  id: number;
  color: string | null;
  entryPasses: Array<Pass>;
  jetPasses: Array<Pass>;
  numberOfEntryTickets: number;
  numberOfJetpasses: number;
  entryPassSelectionComplete: boolean;
  jetpassSelectionComplete: boolean;
};
export type GuestInput = Omit<Guest, "id" | "color" | "jetpassSelectionComplete" | "entryPassSelectionComplete"> & {
  product: {
    glkId: number;
    productName: string;
  };
  productTimeLimit: TimeLimits | null;
  additionalInfo: Record<string, unknown>;
};

export type SelectionData = {
  guests: Array<Guest>;
  date: Date | string;
};

export type JetpassModalContextType =
  | {
      showJetPassModal: false;
    }
  | {
      showJetPassModal: true;
      jetPassDate: Date | string;
      onSelectJetpassComplete: (selectionData: SelectionData) => void;
      jetPassOptions?: {
        disableIntro?: boolean;
        customHeadingEntrypass?: string;
        customHeadingJetpass?: string;
        alreadySelectedJetpasses?: Array<{
          beingEdited?: boolean;
          attractionId: number;
          name: string;
          time: string;
        }>;
        filterOutTimesBefore?: Date | string;
        enableBackButton?: boolean;
      };
      guests: Array<GuestInput>;
    };
const JetpassModalContext = createContext<
  [JetpassModalContextType, Dispatch<SetStateAction<JetpassModalContextType>>] | undefined
>(undefined);

type ContextProps = PropsWithChildren;

export const JetpassModalContextProvider = ({ children }: ContextProps) => {
  const pair = useState<JetpassModalContextType>({ showJetPassModal: false });
  return <JetpassModalContext.Provider value={pair}>{children}</JetpassModalContext.Provider>;
};

export const JetpassModalContextConsumer = JetpassModalContext.Consumer;

export const useJetpassModalContext = () => {
  const context = useContext(JetpassModalContext);

  if (!context) {
    throw new Error("useJetpassModalContext must be used within a JetpassModalContextProvider");
  }

  return context;
};
