const hasSelectedJetpassesBeforePickedEntryTime = (guests: Array<Guest>, selectedEntryTimeSlotFrom: string) => {
  const entryTimeSlotFrom = dayjs(selectedEntryTimeSlotFrom);
  return guests.every((guest) =>
    guest.admissionProduct.selectedJetpasses.find((jetpass) => {
      const jetpassTimeSlotFrom = dayjs(jetpass.timeSlotFrom);
      return jetpassTimeSlotFrom.isBefore(entryTimeSlotFrom);
    }),
  );
};

const getSelectedTimeSlotsFromEntrancesArray = (
  entrances: Array<IGLKMyParksEntranceWithProductId>,
  selectedTimeSlot: string | Date,
): Array<ITimeSlot> => {
  const foundEntranceTimeSlotsArray: Array<ITimeSlot> = [];

  for (const [index, entrance] of entrances.entries()) {
    const foundEntranceTimeSlots = entrance.timeSlots.find((entranceTimeSlot) => {
      const entranceTimeSlotFrom = DateHelper.toStringTimeHHMM(entranceTimeSlot.timeSlotFrom);
      const selectedTimeSlotFrom = DateHelper.toStringTimeHHMM(selectedTimeSlot);
      return entranceTimeSlotFrom === selectedTimeSlotFrom;
    });

    if (foundEntranceTimeSlots) {
      foundEntranceTimeSlotsArray.push({ ...foundEntranceTimeSlots, productId: entrance.productId });
      continue;
    }
    const pseudoTimeSlot = { ...foundEntranceTimeSlotsArray[0] };
    pseudoTimeSlot.timeSlotFrom = `${DateHelper.toStringTimeYYYYMMDDHHMM(
      DateHelper.addDays(pseudoTimeSlot.timeSlotFrom, index),
    )}:00`;
    pseudoTimeSlot.timeSlotTo = `${DateHelper.toStringTimeYYYYMMDDHHMM(
      DateHelper.addDays(pseudoTimeSlot.timeSlotTo, index),
    )}:00`;
    foundEntranceTimeSlotsArray.push(pseudoTimeSlot);
  }
  return foundEntranceTimeSlotsArray;
};

const getSelectedUpsellProductsBeforePickedEntryTime = (
  selectedUpsellProducts: Map<number, SelectedUpsellProduct>,
  upsellProducts: ReadonlyMap<number, NormalizedProduct>,
  selectedEntryTimeSlotFrom: string,
): Array<UpsellProductsForDate> => {
  const selectedUpsellProductsCopy = new Map(selectedUpsellProducts);
  const entryTimeSlotFrom = dayjs(selectedEntryTimeSlotFrom);
  const upsellProductsBeforeEntryTime = new Array<UpsellProductsForDate>();

  for (const selectedUpsellProduct of [...selectedUpsellProductsCopy.values()]) {
    const timeSlotFrom = selectedUpsellProduct?.timeSlot?.timeSlotFrom;
    if (!timeSlotFrom) {
      continue;
    }
    if (upsellProducts.get(selectedUpsellProduct.productId)?.contentfulProduct?.purchasableOutsideEntryTime) {
      selectedUpsellProductsCopy.delete(selectedUpsellProduct.productId);
    }

    const upsellTimeSlotFrom = dayjs(timeSlotFrom);

    if (
      !upsellTimeSlotFrom.isAfter(entryTimeSlotFrom) &&
      upsellProductsBeforeEntryTime.find(
        (upsellProductsForDate) =>
          DateHelper.toStringYYYYMMDD(upsellProductsForDate.date) === DateHelper.toStringYYYYMMDD(timeSlotFrom),
      ) === undefined
    ) {
      upsellProductsBeforeEntryTime.push({ date: timeSlotFrom, upsellProducts: selectedUpsellProductsCopy });
    }
  }

  return upsellProductsBeforeEntryTime;
};

const mapAndSortVisitorCategories = (
  visitorCategories: Record<VisitorCategory["id"], VisitorCategory>,
): Map<VisitorCategory["id"], VisitorCategory> => {
  if (!Object.keys(visitorCategories)) {
    return new Map();
  }

  const visitorCategoryEntries = Object.entries(visitorCategories);
  const sortedVisitorCategories = sortBy(visitorCategoryEntries, ["[1].sortIndex"]);
  return new Map(sortedVisitorCategories) as Map<VisitorCategory["id"], VisitorCategory>;
};

const sortProductsByVisitorCategorySortIndex = (
  products: Array<Product>,
  visitorCategories: Map<VisitorCategory["id"], VisitorCategory>,
) => {
  const sortIndexes = products.map((product) => {
    const visitorCategoryId = product.productMetadata.visitorCategory;
    const visitorCategory = visitorCategoryId && visitorCategories.get(visitorCategoryId);
    const sortIndex = visitorCategory?.sortIndex ?? 1000;
    return sortIndex;
  });
  const productIndexesSorted = range(products.length).sort((a, b) => {
    const sortIndexForA = sortIndexes[a];
    const sortIndexForB = sortIndexes[b];
    if (sortIndexForA < sortIndexForB) {
      return 1;
    } else if (sortIndexForA > sortIndexForB) {
      return -1;
    }
    return 0;
  });

  return productIndexesSorted.map((index) => products[index]);
};

const getNextStepCompletedStatus = (steps: Array<StepData>, isCompleted: Map<Step, boolean>, activeStep: number) => {
  if (isNonEmptyArray(steps) && isCompleted.size > 0) {
    const currentStepIsLastStep = activeStep === steps.length - 1;
    if (!currentStepIsLastStep) {
      const nextStep = steps[activeStep + 1].stepType;
      return isCompleted.get(nextStep);
    }
  }
  return false;
};

const mapTimeSlotToSelectablePass = (
  timeSlot: ITimeSlot,
  productId: number,
  attractionId: number,
  attractionName: string,
): SelectablePass => {
  return {
    productId,
    timeSlotId: timeSlot.timeSlotId,
    timeSlotFrom: timeSlot.timeSlotFrom,
    timeSlotTo: timeSlot.timeSlotTo,
    quantity: timeSlot.quantity,
    attractionId,
    attractionName,
  };
};

const getSortedVariantsFromSelection = (products: Array<Product>, entryVariants: Record<string, EntryVariant>) => {
  const variants = products
    .map((product) => product?.productMetadata?.entryVariant)
    .filter(isTruthy)
    // Keep only unique entryVariant ids
    .filter((variant, index, arr) => arr.indexOf(variant) === index);

  variants.sort((variantA, variantB) => {
    const entryVariantA = entryVariants[variantA];
    const entryVariantB = entryVariants[variantB];
    if (entryVariantA.sortIndex < entryVariantB.sortIndex) {
      return -1;
    } else if (entryVariantA.sortIndex > entryVariantB.sortIndex) {
      return 1;
    } else {
      return 0;
    }
  });

  return variants;
};

const getMappedProductsFromSelectedVariants = (
  products: Array<ProductWithQuantity>,
  selectedVariants: Array<EntryVariant["id"]>,
): Map<EntryVariant["id"], Array<ProductWithQuantity>> => {
  return new Map(
    selectedVariants
      .map((variant) => {
        const productsForVariant = products.filter((product) => product.productMetadata.entryVariant === variant);
        return [variant, productsForVariant] as const;
      })
      .filter(([, products]) => products.length > 0),
  );
};

export type ProductWithTicketsForQuantity = Product & { ticketsForQuantity: boolean };
export type PurchaseFlowWithTicketsForQuantity = PurchaseFlowDate & { products: Array<ProductWithTicketsForQuantity> };

const atLeastOneVariantHasTicketsLeft = (products: Array<ProductWithTicketsForQuantity>) => {
  const uniqueEntryVariants = uniqBy(products, "productMetadata.entryVariant").map(
    (product) => product.productMetadata.entryVariant,
  );

  const checkIfVariantHasTicketsLeft = (variant: EntryVariant["id"] | undefined) => {
    return products
      .filter((product) => product.productMetadata.entryVariant === variant)
      .every((product) => {
        return product.ticketsForQuantity === true;
      });
  };

  return uniqueEntryVariants.some((variant) => checkIfVariantHasTicketsLeft(variant));
};

const scrollAndCompleteStep = (
  element: HTMLElement,
  step: Step,
  dispatch: Dispatch<Action>,
  alwaysAnimateScroll = false,
) => {
  const wrapperHeight = element?.clientHeight ?? 0;
  if (alwaysAnimateScroll || wrapperHeight > window.innerHeight * 0.9) {
    try {
      animatedScrollTo(element, { verticalOffset: -48, speed: 1350, maxDuration: 500 });
    } catch (error) {
      console.error("Error scrolling to element. Continuing without scrolling.", error);
    }
  }
  dispatch({ type: ActionType.COMPLETE_STEP, payload: { completedStep: step } });
};

const getLowestPriceLevel = (products: Array<Product>, visitorCategories: Array<VisitorCategory>) => {
  let filteredProducts = products;

  if (!isNonEmptyArray(filteredProducts)) {
    return null;
  }

  if (isNonEmptyArray(visitorCategories)) {
    const uniqueVisitorCategoriesInProducts = new Set(
      products.map((product) => product?.productMetadata?.visitorCategory),
    );

    const visitorCategoriesRelevantForTheseProduct = visitorCategories.filter((visitorCategory) =>
      uniqueVisitorCategoriesInProducts.has(visitorCategory.id),
    );

    if (!isNonEmptyArray(visitorCategoriesRelevantForTheseProduct)) {
      return null;
    }

    const visitorCategoryWithLowestPriority = visitorCategoriesRelevantForTheseProduct.reduce((prev, curr) =>
      prev.priceLevelPresenterPriority < curr.priceLevelPresenterPriority ? prev : curr,
    );

    filteredProducts = products.filter(
      (product) => product?.productMetadata?.visitorCategory === visitorCategoryWithLowestPriority.id,
    );
  }

  const priceLevels = filteredProducts
    .map((product) => product?.productMetadata?.priceLevel)
    .filter((priceLevel) => typeof priceLevel === "number");

  return Math.min(...priceLevels);
};

const hasGuestsExeededJetpassLimit = (guests: Array<Guest>, jetpassMaxLimit?: number) => {
  // If jetpassMaxLimit is not set, we don't want to limit the amount of jetpasses
  // Important! We should not write if(!jetpassMaxLimit) because 0 is a valid value, !0 === true.
  if (jetpassMaxLimit === undefined || jetpassMaxLimit === null) return false;

  return (
    guests.reduce((acc, guest) => {
      const hasJetpasses = guest?.admissionProduct?.numberOfJetpassIncluded > 0;
      return acc + (hasJetpasses ? 1 : 0);
    }, 0) > jetpassMaxLimit
  );
};

const getRadioPickerValueFromProduct = (product: ProductWithQuantity) => {
  return `${product.productId}_${product.productMetadata.visitorCategory}`;
};

const GroupAdmissionHelper = {
  hasSelectedJetpassesBeforePickedEntryTime,
  getSelectedTimeSlotsFromEntrancesArray,
  getSelectedUpsellProductsBeforePickedEntryTime,
  sortProductsByVisitorCategorySortIndex,
  mapAndSortVisitorCategories,
  getNextStepCompletedStatus,
  mapTimeSlotToSelectablePass,
  getSortedVariantsFromSelection,
  getMappedProductsFromSelectedVariants,
  atLeastOneVariantHasTicketsLeft,
  scrollAndCompleteStep,
  getLowestPriceLevel,
  hasGuestsExeededJetpassLimit,
  getRadioPickerValueFromProduct,
};

export default GroupAdmissionHelper;
